<?php
putenv('BRAINPRESS_DSN=sqlite::memory:');require dirname(__DIR__).'/src/bootstrap.php';require dirname(__DIR__).'/src/components.php';require dirname(__DIR__).'/src/admin-navigation.php';
function navigationCheck(bool $ok,string $message): void {if(!$ok)throw new RuntimeException($message);echo "PASS $message\n";}
foreach(['posts'=>'/admin/posts','categories'=>'/admin/categories','links'=>'/admin/links'] as $section=>$url){$_GET=[];ob_start();renderAdminNavigation($section);$html=ob_get_clean();navigationCheck(substr_count($html,'class="admin-nav-group" open')===1,'Current management group opens for '.$section);navigationCheck(str_contains($html,'href="'.$url.'" class="active" aria-current="page"'),'Current submenu is selected for '.$section);}
$_GET=['link_categories'=>'1'];ob_start();renderAdminNavigation('links');$html=ob_get_clean();navigationCheck(str_contains($html,'href="/admin/links?link_categories=1" class="active" aria-current="page"'),'Link category page selects its own submenu');navigationCheck(!str_contains($html,'href="/admin/links" class="active"'),'Link list is not also selected');$_GET=[];ob_start();renderAdminNavigation('media');$html=ob_get_clean();navigationCheck(substr_count($html,'class="admin-nav-group" open')===1,'Only media management starts open');navigationCheck(str_contains($html,'href="/admin/media" class="active"'),'Media library submenu remains active');navigationCheck(substr_count($html,'<details')===5&&str_contains($html,'<summary'),'Groups use native keyboard-accessible expansion controls');

foreach(['tags'=>'/admin/tags','menus'=>'/admin/menus','tabs'=>'/admin/tabs','users'=>'/admin/users'] as $section=>$url){$_GET=[];ob_start();renderAdminNavigation($section);$html=ob_get_clean();navigationCheck(str_contains($html,'href="'.$url.'"')&&str_contains($html,'aria-current="page"'),'Updated navigation selects '.$section);}
